const ENDPOINT = 'PUT /2/tweets/:id/hidden';
// X allows 50 hides per 15 minutes per token. Never claim more than one
// full window in a single pass even if allowance somehow reads higher.
const MAX_BATCH = 50;
const REFRESH_BUFFER_MS = 2 * 60 * 1000;
const CANNOT_REFRESH_DEFER_MS = 10 * 60 * 1000;

function envValue(name) {
  try {
    if (typeof $env === 'undefined' || !$env) return '';
    return String($env[name] || '');
  } catch (error) {
    return '';
  }
}

// The router keeps the X OAuth client credentials inline in a Code node. The
// drain deliberately does NOT copy that secret into a second workflow: it
// reads instance environment variables instead. When they are unset the drain
// defers stale-token rows rather than burning attempts on a 401 it cannot fix.
const clientId = envValue('X_OAUTH_CLIENT_ID');
const clientSecret = envValue('X_OAUTH_CLIENT_SECRET');
const canRefresh = Boolean(clientId && clientSecret);
const nowMs = Date.now();

return $input.all().map(function (item) {
  const row = item.json || {};
  const xUserId = String(row.x_user_id || '');
  const base = {
    x_user_id: xUserId,
    x_username: row.x_username || '',
    telegram_chat_id: row.account_chat_id || null,
    due_count: Number(row.due_count || 0),
    endpoint: ENDPOINT,
    can_refresh: canRefresh,
  };

  if (!row.has_account || !row.access_token) {
    return { json: Object.assign({}, base, {
      mode: 'block',
      access_token: '',
      allowance: 0,
      block_code: 'x_auth_rejected',
      block_reason: 'No connected X account for x_user_id ' + xUserId
        + '. Reconnect that account with /auth_x, then hide again.',
    }) };
  }

  const allowance = Math.max(0, Math.min(Number(row.allowance || 0), MAX_BATCH));
  const resetAt = row.reset_at ? new Date(row.reset_at).toISOString() : '';

  // Section 2.2 step 3: quota gone and the window is still open -> push the
  // rows past the reset and spend no requests at all.
  if (allowance <= 0) {
    return { json: Object.assign({}, base, {
      mode: 'defer',
      access_token: '',
      allowance: 0,
      defer_until: resetAt || new Date(nowMs + CANNOT_REFRESH_DEFER_MS).toISOString(),
      defer_code: 'x_rate_limited',
      defer_reason: 'X hide quota for ' + xUserId + ' is spent; window resets at '
        + (resetAt || 'an unknown time') + '.',
      alert: false,
    }) };
  }

  const expiresAtMs = row.expires_at ? new Date(row.expires_at).getTime() : 0;
  const tokenStale = !expiresAtMs || Number.isNaN(expiresAtMs)
    || expiresAtMs <= nowMs + REFRESH_BUFFER_MS;

  if (tokenStale && !row.refresh_token) {
    return { json: Object.assign({}, base, {
      mode: 'block',
      access_token: '',
      allowance: 0,
      block_code: 'x_auth_rejected',
      block_reason: 'The X connection for ' + xUserId
        + ' expired and has no refresh token. Send /auth_x again.',
    }) };
  }

  if (tokenStale && !canRefresh) {
    return { json: Object.assign({}, base, {
      mode: 'defer',
      access_token: '',
      allowance: 0,
      defer_until: new Date(nowMs + CANNOT_REFRESH_DEFER_MS).toISOString(),
      defer_code: 'drain_cannot_refresh',
      defer_reason: 'Access token for ' + xUserId + ' is stale and the drain cannot refresh it: X_OAUTH_CLIENT_ID / X_OAUTH_CLIENT_SECRET are not set on this n8n instance. Rows deferred, not failed.',
      alert: true,
    }) };
  }

  return { json: Object.assign({}, base, {
    mode: 'drain',
    needs_refresh: tokenStale,
    allowance: allowance,
    access_token: row.access_token,
    refresh_token: row.refresh_token || '',
    expires_at: row.expires_at || null,
    reset_at: resetAt,
  }) };
});

function envValue(name) {
  try {
    if (typeof $env === 'undefined' || !$env) return '';
    return String($env[name] || '');
  } catch (error) {
    return '';
  }
}

const clientId = envValue('X_OAUTH_CLIENT_ID');
const clientSecret = envValue('X_OAUTH_CLIENT_SECRET');

if (!clientId || !clientSecret) {
  throw new Error('X_OAUTH_CLIENT_ID / X_OAUTH_CLIENT_SECRET are not set on this n8n instance. Plan Drain Pass should have deferred this token instead of routing it here.');
}

const authorization = 'Basic ' + Buffer.from(clientId + ':' + clientSecret).toString('base64');

return $input.all().map(function (item) {
  return { json: Object.assign({}, item.json, { authorization: authorization }) };
});

const CANNOT_REFRESH_DEFER_MS = 10 * 60 * 1000;
const requests = $('Prepare Drain Refresh Request').all().map(function (item) {
  return item.json || {};
});

function parseJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (error) { return value; }
}

function statusOf(response) {
  const candidates = [
    response && response.statusCode,
    response && response.status,
    response && response.error && response.error.statusCode,
  ];
  for (const candidate of candidates) {
    const parsed = Number(candidate);
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }
  return null;
}

return $input.all().map(function (item, index) {
  const previous = requests[index] || {};
  const response = item.json || {};
  const body = parseJson(response.body !== undefined ? response.body : response) || {};
  const statusCode = statusOf(response);
  const accessToken = body.access_token || '';

  if (accessToken) {
    const expiresIn = Number(body.expires_in || 0);
    return { json: Object.assign({}, previous, {
      refresh_ok: true,
      access_token: accessToken,
      refresh_token: body.refresh_token || previous.refresh_token || '',
      expires_at: expiresIn > 0
        ? new Date(Date.now() + expiresIn * 1000).toISOString()
        : previous.expires_at,
      scope: body.scope || '',
    }) };
  }

  const detail = String(
    body.error_description || body.error || body.detail || body.title
      || ('HTTP ' + statusCode)
  ).slice(0, 500);

  // invalid_grant means the refresh token itself is dead -- reconnecting is the
  // only fix, so fail the rows rather than retrying five times against a wall.
  const permanent = statusCode === 400 || statusCode === 401
    || /invalid_grant|invalid_request|unauthorized_client/i.test(String(body.error || ''));

  if (permanent) {
    return { json: Object.assign({}, previous, {
      refresh_ok: false,
      refresh_failure_mode: 'block',
      block_code: 'x_auth_rejected',
      block_reason: 'X refused to refresh the token for ' + previous.x_user_id
        + ': ' + detail + '. Reconnect that account with /auth_x.',
    }) };
  }

  return { json: Object.assign({}, previous, {
    refresh_ok: false,
    refresh_failure_mode: 'defer',
    defer_until: new Date(Date.now() + CANNOT_REFRESH_DEFER_MS).toISOString(),
    defer_code: 'x_unavailable',
    defer_reason: 'Token refresh for ' + previous.x_user_id
      + ' failed transiently: ' + detail,
    alert: false,
  }) };
});

// Two branches feed this node: tokens that needed no refresh (straight from
// "If Token Needs Refresh") and tokens just refreshed (from the RETURNING of
// "Upsert Refreshed Drain Account"). Normalise both to one shape so the claim
// query does not care which path an item took.
return $input.all().map(function (item) {
  const row = item.json || {};
  return { json: {
    x_user_id: String(row.x_user_id || ''),
    x_username: row.x_username || '',
    telegram_chat_id: row.telegram_chat_id || null,
    access_token: row.access_token || '',
    allowance: Math.max(0, Number(row.allowance || 0)),
  } };
}).filter(function (item) {
  return item.json.x_user_id && item.json.access_token && item.json.allowance > 0;
});

// Claimed rows come back from Postgres without the token that pays for them.
// Look the token up by x_user_id rather than relying on paired-item resolution
// across the refresh branch, which is not guaranteed through a DB node.
const tokens = new Map();
for (const item of $('Ready To Claim').all()) {
  const row = item.json || {};
  if (row.x_user_id) tokens.set(String(row.x_user_id), row);
}

return $input.all().filter(function (item) {
  return item.json && item.json.id;
}).map(function (item) {
  const row = item.json;
  const token = tokens.get(String(row.x_user_id)) || {};
  return { json: Object.assign({}, row, {
    access_token: token.access_token || '',
    x_username: token.x_username || '',
    endpoint: 'PUT /2/tweets/:id/hidden',
  }) };
});

const ENDPOINT = 'PUT /2/tweets/:id/hidden';
// Section 2.2 step 5.
const MAX_ATTEMPTS = 5;

const requests = $('Prepare Hide Requests').all().map(function (item) {
  return item.json || {};
});

function parseJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (error) { return value; }
}

function asText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try { return JSON.stringify(value); } catch (error) { return String(value); }
}

function cleanText(value, maxLength) {
  const limit = maxLength || 700;
  return asText(value).replace(/\s+/g, ' ').trim().slice(0, limit);
}

function extractBody(response) {
  if (response && Object.prototype.hasOwnProperty.call(response, 'body')) {
    return parseJson(response.body);
  }
  return parseJson(response);
}

function extractStatusCode(response) {
  const candidates = [
    response && response.statusCode,
    response && response.status,
    response && response.response && response.response.statusCode,
    response && response.error && response.error.statusCode,
  ];
  for (const candidate of candidates) {
    const parsed = Number(candidate);
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }
  return null;
}

function extractHeaders(response) {
  return (response && response.headers)
    || (response && response.response && response.response.headers)
    || (response && response.error && response.error.headers)
    || {};
}

function headerValue(headers, name) {
  const wanted = name.toLowerCase();
  for (const entry of Object.entries(headers || {})) {
    if (String(entry[0]).toLowerCase() === wanted) {
      return Array.isArray(entry[1]) ? entry[1][0] : entry[1];
    }
  }
  return '';
}

function extractRateLimit(response) {
  const headers = extractHeaders(response);
  const limit = Number(headerValue(headers, 'x-rate-limit-limit'));
  const remaining = Number(headerValue(headers, 'x-rate-limit-remaining'));
  const reset = Number(headerValue(headers, 'x-rate-limit-reset'));
  return {
    has_any: Number.isFinite(limit) || Number.isFinite(remaining) || Number.isFinite(reset),
    limit: Number.isFinite(limit) ? limit : null,
    remaining: Number.isFinite(remaining) ? remaining : null,
    reset: Number.isFinite(reset) ? reset : null,
    reset_at: Number.isFinite(reset) && reset > 0
      ? new Date(reset * 1000).toISOString() : '',
  };
}

function pushPart(parts, value) {
  const text = cleanText(value);
  if (text && !parts.includes(text)) parts.push(text);
}

function extractErrorText(response, body) {
  const parts = [];
  const errors = Array.isArray(body && body.errors) ? body.errors : [];
  pushPart(parts, body && body.title);
  pushPart(parts, body && body.detail);
  pushPart(parts, body && body.message);
  pushPart(parts, body && body.error_description);
  pushPart(parts, body && body.error);
  for (const error of errors) {
    pushPart(parts, error && error.title);
    pushPart(parts, error && error.detail);
    pushPart(parts, error && error.message);
    pushPart(parts, error && error.code);
    pushPart(parts, error && error.type);
  }
  pushPart(parts, response && response.message);
  pushPart(parts, response && response.error && response.error.message);
  return parts.join(' | ');
}

// Categories are copied verbatim from the router node "Prepare Hide Result"
// so the queue classifies failures exactly as the inline path used to.
function classifyFailure(statusCode, errorText, body) {
  const lower = errorText.toLowerCase();
  const title = cleanText(body && body.title, 160);
  const detail = cleanText((body && body.detail) || errorText, 700);

  function result(code, reason, userMessage) {
    return { code: code, reason: reason, userMessage: userMessage };
  }

  if (lower.includes('already hidden') || (lower.includes('already') && lower.includes('hidden'))) {
    return result('already_hidden', 'Reply was already hidden on X.',
      'X says one or more replies were already hidden.');
  }
  if (statusCode === 401 || lower.includes('invalid token') || lower.includes('expired token')
    || lower.includes('token expired') || lower.includes('revoked')) {
    return result('x_auth_rejected', detail || 'X rejected the access token.',
      'X rejected the connected account token. Reconnect the owning X account with /auth_x and try again.');
  }
  if (lower.includes('tweet.moderate.write') || lower.includes('scope')
    || lower.includes('permission') || lower.includes('permissions')) {
    return result('missing_moderation_permission',
      detail || 'X says the token is missing moderation permission.',
      'The connected X account is missing moderation permission. Reconnect with /auth_x so X grants tweet.moderate.write.');
  }
  if (lower.includes('owner') || lower.includes('author') || lower.includes('own this')
    || lower.includes('not authorized') || lower.includes('forbidden') || lower.includes('not allowed')) {
    return result('not_post_owner_or_not_moderatable',
      detail || 'X refused moderation for this reply.',
      'X would not let the connected account hide this reply. Confirm the connected account owns the original post.');
  }
  if (statusCode === 403) {
    return result('x_moderation_forbidden', detail || title || 'X returned 403 Forbidden.',
      'X rejected the hide request as forbidden. Confirm ownership and moderation permissions.');
  }
  if (statusCode === 404 || lower.includes('not found') || lower.includes('does not exist')
    || lower.includes('deleted')
    || (statusCode === 400 && (lower.includes('invalid-request')
      || lower.includes('one or more parameters')))) {
    return result('reply_not_found', detail || 'The reply was not found on X.',
      'X could not find the reply. It may have been deleted or is no longer available.');
  }
  if (statusCode === 429 || lower.includes('rate limit') || lower.includes('too many requests')) {
    return result('x_rate_limited', detail || 'X rate limited the hide request.',
      'X rate limit reached. The queue will retry automatically.');
  }
  if (statusCode && statusCode >= 500) {
    return result('x_unavailable', detail || ('X returned HTTP ' + statusCode + '.'),
      'X returned a server error while hiding replies.');
  }
  if (lower.includes('econn') || lower.includes('timeout') || lower.includes('network')
    || lower.includes('socket')) {
    return result('network_error', detail || 'Network error while calling X.',
      'The hide request could not reach X reliably.');
  }
  if (statusCode) {
    return result('x_hide_rejected', detail || title || ('X returned HTTP ' + statusCode + '.'),
      'X rejected the hide request with HTTP ' + statusCode + '.');
  }
  return result('x_hide_not_confirmed', detail || 'X did not confirm the reply was hidden.',
    'X did not confirm that the reply was hidden.');
}

// Verified against live X on 2026-08-27, not assumed: a deleted reply returns
// 400 invalid-request (handled above), and X refuses to hide a SELF-authored
// reply with a bare 403 Forbidden -> not_post_owner_or_not_moderatable.
//
// Section 2.2 step 5: "Permanent failures (deleted reply, revoked token,
// non-owner) must not be retried". Everything outside this set is retried
// until MAX_ATTEMPTS.
const PERMANENT = [
  'x_auth_rejected',
  'missing_moderation_permission',
  'not_post_owner_or_not_moderatable',
  'x_moderation_forbidden',
  'reply_not_found',
];

const outcomes = [];
const replyUpdates = [];
const rateLimitByToken = new Map();
const deferByToken = new Map();
const batchIds = [];
const results = [];
let hidden = 0;
let failed = 0;
let abandoned = 0;
let requeued = 0;
let rateLimited = 0;

const items = $input.all();

items.forEach(function (item, index) {
  const original = requests[index] || {};
  const response = item.json || {};
  const body = extractBody(response) || {};
  const statusCode = extractStatusCode(response);
  const rateLimit = extractRateLimit(response);
  const xUserId = String(original.x_user_id || '');

  if (rateLimit.has_any && xUserId) {
    rateLimitByToken.set(xUserId, {
      x_user_id: xUserId,
      endpoint: ENDPOINT,
      limit_ceiling: rateLimit.limit,
      remaining: rateLimit.remaining,
      reset_at: rateLimit.reset_at || null,
    });
  }

  const confirmedHidden = (body && body.data && body.data.hidden === true)
    || (response && response.data && response.data.hidden === true);
  const errorText = extractErrorText(response, body);
  const hasError = Boolean(errorText || (response && response.error)
    || (statusCode && statusCode >= 400));
  const classification = confirmedHidden && !hasError
    ? { code: '', reason: '', userMessage: '' }
    : classifyFailure(statusCode, errorText, body);

  const alreadyHidden = classification.code === 'already_hidden';
  const success = confirmedHidden || alreadyHidden;
  const attempts = Number(original.attempts || 0);
  const batchId = original.batch_id ? String(original.batch_id) : '';
  if (batchId && !batchIds.includes(batchId)) batchIds.push(batchId);

  let nextStatus;
  let notBefore = null;
  let attemptsDelta = 0;

  if (success) {
    nextStatus = 'done';
    hidden += 1;
    replyUpdates.push({ reply_id: String(original.reply_id || ''), status: 'hidden' });
  } else if (classification.code === 'x_rate_limited') {
    // A 429 says nothing about whether this reply can be hidden, so the
    // attempt is refunded and the row is pushed past the window reset.
    nextStatus = 'queued';
    attemptsDelta = -1;
    rateLimited += 1;
    requeued += 1;
    notBefore = rateLimit.reset_at || new Date(Date.now() + 15 * 60 * 1000).toISOString();
    if (xUserId) {
      deferByToken.set(xUserId, { x_user_id: xUserId, defer_until: notBefore });
      if (!rateLimitByToken.has(xUserId)) {
        rateLimitByToken.set(xUserId, {
          x_user_id: xUserId,
          endpoint: ENDPOINT,
          limit_ceiling: rateLimit.limit,
          remaining: 0,
          reset_at: notBefore,
        });
      } else {
        rateLimitByToken.get(xUserId).remaining = 0;
      }
    }
  } else if (PERMANENT.includes(classification.code)) {
    nextStatus = 'failed';
    failed += 1;
    replyUpdates.push({ reply_id: String(original.reply_id || ''), status: 'hide_failed' });
  } else if (attempts >= MAX_ATTEMPTS) {
    nextStatus = 'abandoned';
    abandoned += 1;
    replyUpdates.push({ reply_id: String(original.reply_id || ''), status: 'hide_failed' });
  } else {
    nextStatus = 'queued';
    requeued += 1;
    const backoffMinutes = Math.min(Math.pow(2, attempts), 32);
    notBefore = new Date(Date.now() + backoffMinutes * 60 * 1000).toISOString();
  }

  outcomes.push({
    id: original.id,
    status: nextStatus,
    last_error: success ? null : cleanText(classification.reason || errorText || 'Unknown X hide failure.'),
    last_error_code: success ? null : classification.code,
    not_before: notBefore,
    attempts_delta: attemptsDelta,
  });

  results.push({
    reply_id: original.reply_id,
    post_id: original.post_id,
    x_user_id: xUserId,
    queue_status: nextStatus,
    success: success,
    code: success ? '' : classification.code,
    reason: success ? '' : cleanText(classification.reason || errorText, 400),
    user_message: success ? "" : classification.userMessage,
    status_code: statusCode,
    attempts: attempts,
  });
});

const rateLimits = Array.from(rateLimitByToken.values());
const deferTokens = Array.from(deferByToken.values());

return [{ json: {
  attempted: items.length,
  hidden: hidden,
  failed: failed,
  abandoned: abandoned,
  requeued: requeued,
  rate_limited: rateLimited,
  outcomes_json: JSON.stringify(outcomes),
  reply_updates_json: JSON.stringify(replyUpdates),
  rate_limits_json: JSON.stringify(rateLimits),
  defer_tokens_json: JSON.stringify(deferTokens),
  batch_ids_csv: batchIds.join(','),
  results: results,
} }];

// Section 2.2 step 4: the drain edits the message the router sent, so the
// user watches one message count up instead of collecting a new one every
// five minutes.
function escapeHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, "&quot;");
}

function clockTime(value) {
  if (!value) return '';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return '';
  return parsed.toISOString().slice(11, 16) + ' UTC';
}

return $input.all().filter(function (item) {
  const row = item.json || {};
  return row.telegram_chat_id && row.telegram_message_id;
}).map(function (item) {
  const row = item.json;
  const total = Number(row.total || 0);
  const done = Number(row.done || 0);
  const failed = Number(row.failed || 0);
  const pending = Number(row.pending || 0);
  const resumeAt = clockTime(row.next_attempt_at);

  const lines = [
    pending > 0 ? '<b>Hiding replies</b>' : '<b>Hide replies complete</b>',
    'Post: <code>' + escapeHtml(row.post_id) + '</code>',
    done + ' of ' + total + ' hidden',
  ];

  if (failed > 0) lines.push(failed + ' could not be hidden');
  if (pending > 0) {
    lines.push(resumeAt ? (pending + ' queued - resuming ' + resumeAt)
      : (pending + ' still queued'));
  }

  return { json: {
    telegram_chat_id: row.telegram_chat_id,
    telegram_message_id: row.telegram_message_id,
    batch_id: row.batch_id,
    message: lines.join('\n'),
  } };
});

const summary = $('Prepare Drain Hide Result').first().json || {};
const results = Array.isArray(summary.results) ? summary.results : [];
const problems = results.filter(function (row) { return !row.success; });

// Silence is the normal case. Only a pass that actually failed something
// alerts, and a plain 429 is not a failure -- the queue handles it.
const alertable = problems.filter(function (row) {
  return row.code !== 'x_rate_limited';
});
if (alertable.length === 0) return [];

function escapeHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, "&quot;");
}

function line(value) {
  return escapeHtml(String(value === null || value === undefined ? '' : value).slice(0, 400));
}

const groups = new Map();
for (const row of alertable) {
  const code = row.code || 'x_hide_not_confirmed';
  const existing = groups.get(code) || {
    code: code,
    count: 0,
    reason: row.reason || '',
    queue_status: row.queue_status || '',
    reply_ids: [],
  };
  existing.count += 1;
  if (row.reply_id) existing.reply_ids.push(String(row.reply_id));
  groups.set(code, existing);
}

const groupLines = Array.from(groups.values()).slice(0, 8).map(function (group) {
  const sample = group.reply_ids.slice(0, 3);
  const more = group.reply_ids.length - sample.length;
  const replies = sample.length
    ? ' Replies: <code>' + line(sample.join(', ')) + (more > 0 ? ' +' + more + ' more' : '') + '</code>'
    : '';
  return '- ' + group.count + ' ' + line(group.code) + ' -> ' + line(group.queue_status)
    + ': ' + line(group.reason || 'No detail') + replies;
});

const message = [
  '<b>XMonitor production handled error</b>',
  'Workflow: Moderation Queue Drain',
  'Path: hide replies X moderation',
  'Attempted: ' + Number(summary.attempted || 0),
  'Hidden: ' + Number(summary.hidden || 0),
  'Failed (permanent): ' + Number(summary.failed || 0),
  'Abandoned (attempts exhausted): ' + Number(summary.abandoned || 0),
  'Requeued: ' + Number(summary.requeued || 0),
  'Rate limited: ' + Number(summary.rate_limited || 0),
  '',
  '<b>Failure groups</b>',
  ...groupLines,
].join('\n').slice(0, 3900);

return [{ json: { developer_chat_id: '8677383067', message: message } }];

// Fed by both "Defer Token Rows" and "Fail Token Rows". Deferrals are
// usually routine (quota spent), so only the ones flagged alert:true and all
// hard blocks are worth a message.
const rows = $input.all().map(function (item) { return item.json || {}; });
if (rows.length === 0) return [];

function escapeHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, "&quot;");
}

const notable = [];

// The DB nodes return ids, not reasons. The reason lives on the plan item
// that routed the token here, so read those nodes by name instead.
let plans = [];
try {
  plans = $('Plan Drain Pass').all().map(function (item) { return item.json || {}; });
} catch (error) {
  plans = [];
}
try {
  plans = plans.concat($('Apply Drain Refresh').all().map(function (item) {
    return item.json || {};
  }));
} catch (error) { /* refresh branch did not run this pass */ }

for (const plan of plans) {
  if (plan.block_code) {
    notable.push({
      kind: 'blocked',
      x_user_id: plan.x_user_id,
      code: plan.block_code,
      reason: plan.block_reason,
    });
  } else if (plan.defer_code && plan.alert === true) {
    notable.push({
      kind: 'deferred',
      x_user_id: plan.x_user_id,
      code: plan.defer_code,
      reason: plan.defer_reason,
    });
  }
}

if (notable.length === 0) return [];

const lines = notable.slice(0, 10).map(function (entry) {
  return '- ' + escapeHtml(entry.kind) + ' ' + escapeHtml(entry.x_user_id) + ' ('
    + escapeHtml(entry.code) + '): ' + escapeHtml(String(entry.reason || '').slice(0, 400));
});

const message = [
  '<b>XMonitor production handled error</b>',
  'Workflow: Moderation Queue Drain',
  'Path: token pre-flight',
  '',
  ...lines,
].join('\n').slice(0, 3900);

return [{ json: { developer_chat_id: '8677383067', message: message } }];
